/// Stores the encrypted base64 API key split into multiple constants.
///
/// These parts were generated by running the bin/encrypt_key.dart local utility.
class EncryptedParts {
  /// First segment of the base64 ciphertext
  static const String part1 = 'O+RRVh4H9JgCj8PbZuuAFb';

  /// Second segment of the base64 ciphertext
  static const String part2 = '77rz0R9FXGEi0cTbiM4WHL';

  /// Third segment of the base64 ciphertext
  static const String part3 = 'aLyjjtM1PCoWgIKXWkOj';

  /// Combines the segments back into the full base64 ciphertext.
  static String getCombinedString() {
    return part1 + part2 + part3;
  }
}
